/**
 * Sous-thèmes « JEUX VIDÉO » (thème GAMING) — données pures, AUCUN import (partagé avec convex/cardsCatalog.ts).
 * GÉNÉRÉ par scripts/make-jeux-video.py (ne pas éditer à la main) depuis Tri-etoiles-jeux-video.xlsx (feuille « Tri étoiles »,
 * colonne « Étoiles » = rareté validée par le groupe) et le journal de récolte des images (scripts/data/jv-harvest.json).
 * 3396 cartes · 177 familles = 177 sous-thèmes (décision du 2 nov.) · clé métier (famille, carte) : 8 homonymes de
 * champions LoL (Jax, Ashe, Morgana…) sont des personnages DIFFÉRENTS, d'où l'identifiant `jv-<famille>-<carte>`.
 * Illustrations : public/art/jv/<famille>--<carte>.(jpg|png) ; sans image → design typographique (src/core/art/jvTitle.ts).
 */
export type JvRarity = 'common' | 'uncommon' | 'rare' | 'epic' | 'legendary' | 'mythic';
export type JvKind = 'cover' | 'character' | 'object';

export interface JvFamily {
  /** identifiant du sous-thème (`jv-<famille>`) — stable */
  id: string;
  label: string;
  /** code court sur la carte (« MAR 012/58 ») */
  code: string;
}

export interface JvEntry {
  /** identifiant de carte (`jv-<famille>-<carte>`) — ne JAMAIS le changer */
  id: string;
  family: string;
  /** numéro dans la famille (1..taille) */
  num: number;
  name: string;
  kind: JvKind;
  rarity: JvRarity;
  /** année de sortie (0 = inconnue) */
  year: number;
  /** illustration (dans art/jv), '' = aucune (design typographique) */
  file: string;
  /** 'c' image pleine (jaquette, capture) · 'i' artwork détouré · '' aucune */
  art: '' | 'c' | 'i';
}

export const JV_INFO = { label: 'Jeux vidéo', artDir: 'art/jv', size: 3396 } as const;

