const counters: number[] = [];
export const JV: JvEntry[] = RAW.map(([f, s, name, k, r, year, file, art]) => {
  const fam = JV_FAMILIES[f];
  counters[f] = (counters[f] ?? 0) + 1;
  return { id: `${fam.id}-${s}`, family: fam.id, num: counters[f], name, kind: K[k], rarity: R[r], year, file, art };
});
